import * as T from './vendor/three.js';
export function objectStyle(project,o={}){return{surface:o.surface||project.style3d?.surface||'lowpoly',detail:o.shapeDetail||project.style3d?.detail||'balanced'}}
export function createScenery(o,style){const flat=style.surface==='lowpoly',detail=style.detail==='chunky'?0:style.detail==='fine'?2:1,sides=flat?style.detail==='chunky'?4:6:20;const group=new T.Group();const mat=color=>new T.MeshStandardMaterial({color,roughness:.85,flatShading:flat});function part(geo,color,x,y,z){const m=new T.Mesh(geo,mat(color));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;group.add(m);return m}if(o.mesh==='tree'){part(new T.CylinderGeometry(.045,.07,.45,sides),'#725039',0,-.275,0);part(new T.ConeGeometry(.43,.7,sides),o.color,0,-.02,0);part(new T.ConeGeometry(.32,.6,sides),o.color,0,.23,0)}else part(flat?new T.IcosahedronGeometry(.5,detail):new T.SphereGeometry(.5,24,16),o.color,0,0,0);group.scale.set(o.w,o.h,o.depth);return group}
